'use client';

import * as React from 'react';

// @interlace/team-board v1.5.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/team-board
// What changed since: https://ds.interlace.tools/c/team-board#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — TeamBoard, TeamScoreboard, TeamBadge
 *
 * Team mode for a live room. The host sets up teams, balances them (or moves a player by hand),
 * and everyone sees whose team they are on and how the teams score. The rules are
 * `games/team-model`; the teams ride in the room (`RoomState.shared`), so a phone that joins late
 * or reconnects shows its team at once and no message can put an old assignment back.
 *
 * ## Anatomy
 *
 *   TeamBoard                      (section — data-slot="team-board", data-state=empty|ready)
 *     ├─ div                       (data-slot="team-board-setup": team count + make teams, before any)
 *     ├─ div role="group"          (data-slot="team-board-actions": shuffle, even out by score)
 *     ├─ ul                        (data-slot="team-board-teams")
 *     │   └─ li × n                (data-slot="team-board-team", data-team-id, data-mark)
 *     │       ├─ h3 + Input        (data-slot="team-board-name": rename on blur or Enter)
 *     │       └─ ul > li × m       (data-slot="team-board-member": name, away, and a "move to" select)
 *     ├─ section                   (data-slot="team-board-unassigned": players with no team yet)
 *     └─ span aria-live            (data-slot="team-board-announce")
 *
 *   TeamScoreboard                 (section — data-slot="team-scoreboard")
 *     ├─ ol > li × n               (data-slot="team-scoreboard-row": rank, mark, name, points, bar)
 *     └─ span aria-live            (data-slot="team-scoreboard-announce": who leads, when it changes)
 *
 *   TeamBadge                      (div role="status" — data-slot="team-badge", data-state=none|team)
 *
 * ## Colour is never alone
 *
 * A team's colour is a `--team-N` token (retune them in your brand layer); each team also has a
 * letter (A, B, C…) and its name, so teams are told apart without seeing colour.
 *
 * ## Keyboard and screen readers
 *
 * Moving a player is a native `<select>` on each member, so there is no drag to do and it works
 * with a keyboard, a switch and a screen reader. The scoreboard is an ordered list and says in
 * words when the leader changes; a phone says when its player moves to another team.
 *
 * ## Motion
 *
 * The scoreboard bars grow with a transition (clamped to none under reduced motion by the page
 * preflight and by `useReducedMotion` here). Nothing else moves.
 *
 * ## MIN_VIEWPORT — 320
 *
 * | Rule | Concept                   | Where in this file                                   |
 * | ---- | ------------------------- | ---------------------------------------------------- |
 * | R4   | Extends native el         | `section` / `div` props                              |
 * | R6   | data-slot per part        | team-board-*, team-scoreboard-*, team-badge         |
 * | R7   | cn + ...rest              | `cn(…, className)` + `{...props}`                    |
 * | R8   | Enums, not booleans       | `by`                                                 |
 * | R14  | Declares min viewport     | `data-min-viewport` + exported const                 |
 * | R25  | Client component          | the board reacts to the room                         |
 * | R26  | A11y                      | lists, labelled selects, sparse live regions         |
 */

import { cn } from '@/lib/utils';
import { useReducedMotion } from '@/hooks/use-reduced-motion';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { RoomHostEvent, RoomPlayer, RoomState } from '@/components/ui/games/room-model';
import type { Random } from '@/components/ui/games/group-model';
import {
  autoBalance,
  createTeams,
  MAX_TEAMS,
  membersOf,
  moveToTeam,
  placeNewcomers,
  readTeams,
  renameTeam,
  teamColor,
  teamMark,
  teamOf,
  teamsEvent,
  teamStandings,
  unassigned,
  type TeamStanding,
  type TeamsState,
} from '@/components/ui/games/team-model';

export const MIN_VIEWPORT = 320 as const;

const SELECT =
  'border-input bg-background text-foreground h-control-sm max-w-full min-w-0 rounded-lg border ps-2 pe-1 text-sm outline-none focus-visible:border-ring focus-visible:ring-ring focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-offset-background';

/** A team's colour as a custom property, so a class can paint with it (`bg-(--team)`). */
const teamStyle = (index: number) => ({ '--team': teamColor(index) }) as React.CSSProperties;

// --- TeamBoard ------------------------------------------------------------------

export interface TeamBoardLabels {
  /** Names the board. @default 'Teams' */
  name?: string;
  /** @default 'Number of teams' */
  count?: string;
  /** @default 'Make teams' */
  make?: string;
  /** Shown before any teams are made. @default 'No teams yet. Choose how many and make them.' */
  empty?: string;
  /** Names the buttons that change the teams. @default 'Team actions' */
  actions?: string;
  /** @default 'Shuffle teams' */
  shuffle?: string;
  /** @default 'Even out by score' */
  evenOut?: string;
  /** @default 'Remove teams' */
  clear?: string;
  /** @default (mark) => `Team ${mark}` */
  team?: (mark: string) => string;
  /** @default (team) => `Name for ${team}` */
  rename?: (team: string) => string;
  /** @default (n) => n === 1 ? '1 player' : `${n} players` */
  size?: (n: number) => string;
  /** @default (player) => `Move ${player} to` */
  move?: (player: string) => string;
  /** The "no team" option. @default 'No team' */
  none?: string;
  /** @default 'away' */
  away?: string;
  /** @default 'No team yet' */
  unassigned?: string;
  /** Said when players are put on teams. @default (n) => `${n} players placed on teams` */
  placed?: (n: number) => string;
}

type TeamBoardProps = Omit<React.ComponentProps<'section'>, 'children'> & {
  room: RoomState;
  /** `send` from the host's `useRoom`. */
  send: (event: RoomHostEvent) => void;
  /** Teams to offer first in the setup. @default 2 */
  defaultTeams?: number;
  /** Put players who join after the teams are made on the smallest team. @default true */
  autoPlace?: boolean;
  /** @default Math.random. Pass `seededRandom(n)` for a split you can repeat. */
  random?: Random;
  labels?: TeamBoardLabels;
};

const SIZE = (n: number) => (n === 1 ? '1 player' : `${n} players`);

function TeamBoard({
  room,
  send,
  defaultTeams = 2,
  autoPlace = true,
  random,
  labels,
  className,
  ...props
}: TeamBoardProps) {
  const L = labels ?? {};
  const teams = readTeams(room);
  const [count, setCount] = React.useState(() => Math.min(MAX_TEAMS, Math.max(2, defaultTeams)));
  const [announce, setAnnounce] = React.useState('');
  const countId = React.useId();
  const latest = React.useRef({ send, random });
  latest.current = { send, random };

  const write = React.useCallback((next: TeamsState | null) => latest.current.send(teamsEvent(next)), []);

  // Someone who joined after the teams were made goes to the smallest team.
  React.useEffect(() => {
    if (!autoPlace || !teams) return;
    const next = placeNewcomers(teams, room.players);
    if (next !== teams) write(next);
  }, [autoPlace, teams, room.players, write]);

  const balance = (scored: boolean) => {
    const base = teams ?? createTeams(count);
    const next = autoBalance(base, room.players, {
      scores: scored ? room.scores : undefined,
      random: latest.current.random,
    });
    write(next);
    setAnnounce((L.placed ?? ((n: number) => `${n} players placed on teams`))(room.players.length));
  };

  const loose = teams ? unassigned(teams, room.players) : [];

  return (
    <section
      aria-label={L.name ?? 'Teams'}
      data-slot="team-board"
      data-state={teams ? 'ready' : 'empty'}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('@container flex flex-col gap-5', className)}
      {...props}
    >
      {teams ? null : (
        <div data-slot="team-board-setup" className="flex flex-wrap items-end gap-3">
          <p className="text-muted-foreground basis-full text-sm">
            {L.empty ?? 'No teams yet. Choose how many and make them.'}
          </p>
          <div className="flex flex-col gap-1.5">
            <label htmlFor={countId} className="text-sm font-medium">
              {L.count ?? 'Number of teams'}
            </label>
            <select
              id={countId}
              data-slot="team-board-count"
              className={SELECT}
              value={count}
              onChange={(e) => setCount(Number(e.target.value))}
            >
              {Array.from({ length: MAX_TEAMS - 1 }, (_, i) => i + 2).map((n) => (
                <option key={n} value={n}>
                  {n}
                </option>
              ))}
            </select>
          </div>
          <Button data-slot="team-board-make" type="button" onClick={() => balance(false)}>
            {L.make ?? 'Make teams'}
          </Button>
        </div>
      )}

      {teams ? (
        <div role="group" aria-label={L.actions ?? 'Team actions'} data-slot="team-board-actions" className="flex flex-wrap gap-2">
          <Button data-slot="team-board-shuffle" type="button" variant="outline" onClick={() => balance(false)}>
            {L.shuffle ?? 'Shuffle teams'}
          </Button>
          <Button data-slot="team-board-even" type="button" variant="outline" onClick={() => balance(true)}>
            {L.evenOut ?? 'Even out by score'}
          </Button>
          <Button data-slot="team-board-clear" type="button" variant="ghost" onClick={() => write(null)}>
            {L.clear ?? 'Remove teams'}
          </Button>
        </div>
      ) : null}

      {teams ? (
        <ul data-slot="team-board-teams" className="grid list-none gap-4 p-0 @2xl:grid-cols-2 @5xl:grid-cols-3">
          {teams.teams.map((team, index) => {
            const people = membersOf(teams, team.id, room.players);
            const mark = teamMark(index);
            return (
              <li
                key={team.id}
                data-slot="team-board-team"
                data-team-id={team.id}
                data-mark={mark}
                style={teamStyle(index)}
                className="bg-card text-card-foreground border-border flex min-w-0 flex-col gap-3 rounded-xl border border-s-4 border-s-(--team) p-4"
              >
                <div className="flex min-w-0 items-center gap-2">
                  <span
                    aria-hidden
                    className="border-border bg-background grid size-7 shrink-0 place-items-center rounded-full border-2 border-(--team) text-sm font-semibold"
                  >
                    {mark}
                  </span>
                  <RenameField
                    key={team.name}
                    label={(L.rename ?? ((n: string) => `Name for ${n}`))(team.name)}
                    value={team.name}
                    onCommit={(name) => write(renameTeam(teams, team.id, name))}
                  />
                </div>
                <p className="text-muted-foreground text-xs tabular-nums">{(L.size ?? SIZE)(people.length)}</p>
                <ul className="flex list-none flex-col gap-1.5 p-0">
                  {people.map((p) => (
                    <MemberRow key={p.id} player={p} teams={teams} labels={L} onMove={(to) => write(moveToTeam(teams, p.id, to))} />
                  ))}
                </ul>
              </li>
            );
          })}
        </ul>
      ) : null}

      {teams && loose.length ? (
        <section data-slot="team-board-unassigned" aria-label={L.unassigned ?? 'No team yet'} className="flex flex-col gap-2">
          <h3 className="text-sm font-semibold">{L.unassigned ?? 'No team yet'}</h3>
          <ul className="flex list-none flex-col gap-1.5 p-0">
            {loose.map((p) => (
              <MemberRow key={p.id} player={p} teams={teams} labels={L} onMove={(to) => write(moveToTeam(teams, p.id, to))} />
            ))}
          </ul>
        </section>
      ) : null}

      <span data-slot="team-board-announce" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </section>
  );
}
TeamBoard.displayName = 'TeamBoard';

/** A team's name as a field: the new name is kept on blur or Enter, and Escape puts the old one back. */
function RenameField({ label, value, onCommit }: { label: string; value: string; onCommit: (name: string) => void }) {
  const [draft, setDraft] = React.useState(value);
  return (
    <Input
      data-slot="team-board-name"
      aria-label={label}
      value={draft}
      maxLength={24}
      className="min-w-0 font-semibold"
      onChange={(e) => setDraft(e.target.value)}
      onBlur={() => draft !== value && onCommit(draft)}
      onKeyDown={(e) => {
        if (e.key === 'Enter') (e.target as HTMLInputElement).blur();
        if (e.key === 'Escape') setDraft(value);
      }}
    />
  );
}

function MemberRow({
  player,
  teams,
  labels,
  onMove,
}: {
  player: RoomPlayer;
  teams: TeamsState;
  labels: TeamBoardLabels;
  onMove: (teamId: string | null) => void;
}) {
  const current = teamOf(teams, player.id)?.id ?? '';
  return (
    <li
      data-slot="team-board-member"
      data-player-id={player.id}
      data-away={player.connected ? undefined : ''}
      className="flex min-w-0 items-center justify-between gap-2"
    >
      <span className={cn('min-w-0 truncate text-sm', !player.connected && 'text-muted-foreground')}>
        {player.name}
        {player.connected ? null : <span className="ms-1.5 text-xs">{labels.away ?? 'away'}</span>}
      </span>
      <select
        data-slot="team-board-move"
        aria-label={(labels.move ?? ((n: string) => `Move ${n} to`))(player.name)}
        className={SELECT}
        value={current}
        onChange={(e) => onMove(e.target.value || null)}
      >
        <option value="">{labels.none ?? 'No team'}</option>
        {teams.teams.map((t, i) => (
          <option key={t.id} value={t.id}>
            {teamMark(i)} · {t.name}
          </option>
        ))}
      </select>
    </li>
  );
}

// --- TeamScoreboard -------------------------------------------------------------

export interface TeamScoreboardLabels {
  /** Names the board. @default 'Team scores' */
  name?: string;
  /** @default (n) => n === 1 ? '1 player' : `${n} players` */
  size?: (n: number) => string;
  /** The points figure's unit, spoken. @default (n, by) => by === 'average' ? `${n} per player` : `${n} points` */
  points?: (n: number, by: 'average' | 'total') => string;
  /** What a round added. @default (n) => `+${n}` */
  gained?: (n: number) => string;
  /** @default (name) => `${name} leads` */
  leads?: (name: string) => string;
  /** Said when two or more share the lead. @default (names) => `${names.join(' and ')} are level` */
  level?: (names: string[]) => string;
  /** Shown before any teams. @default 'No teams yet.' */
  empty?: string;
}

type TeamScoreboardProps = Omit<React.ComponentProps<'section'>, 'children'> & {
  room: Pick<RoomState, 'shared' | 'players' | 'scores' | 'lastPoints'>;
  /** What ranks: `average` is fair when teams differ in size by one. @default 'average' */
  by?: 'average' | 'total';
  /** The viewer's player id, to mark their team. */
  selfId?: string;
  /** For the numbers. @default the page's language */
  locale?: string;
  labels?: TeamScoreboardLabels;
};

function TeamScoreboard({ room, by = 'average', selfId, locale, labels, className, ...props }: TeamScoreboardProps) {
  const L = labels ?? {};
  const fmt = React.useMemo(() => new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }), [locale]);
  const reduced = useReducedMotion();
  const teams = readTeams(room);
  const rows: TeamStanding[] = teams ? teamStandings(teams, room, by) : [];
  const top = rows.length ? Math.max(...rows.map((r) => (by === 'total' ? r.total : r.average))) : 0;
  const mine = teams && selfId ? teamOf(teams, selfId)?.id : undefined;
  const leaders = rows.filter((r) => r.rank === 1);
  const said = React.useRef<string | null>(null);
  const [announce, setAnnounce] = React.useState('');

  // Say who leads, only when it changes (and never on the first look).
  const leadKey = leaders.map((r) => r.id).join(',');
  const leadWords = leaders.length > 1
    ? (L.level ?? ((names: string[]) => `${names.join(' and ')} are level`))(leaders.map((r) => r.name))
    : leaders[0]
      ? (L.leads ?? ((name: string) => `${name} leads`))(leaders[0].name)
      : '';
  React.useEffect(() => {
    const before = said.current;
    said.current = leadKey;
    if (before !== null && before !== leadKey && leadKey && top > 0) setAnnounce(leadWords);
  }, [leadKey, leadWords, top]);

  return (
    <section
      aria-label={L.name ?? 'Team scores'}
      data-slot="team-scoreboard"
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('flex flex-col gap-3', className)}
      {...props}
    >
      {rows.length ? (
        <ol data-slot="team-scoreboard-list" className="flex list-none flex-col gap-3 p-0">
          {rows.map((r) => {
            const value = by === 'total' ? r.total : r.average;
            return (
              <li
                key={r.id}
                data-slot="team-scoreboard-row"
                data-team-id={r.id}
                data-rank={r.rank}
                data-mine={r.id === mine ? '' : undefined}
                style={teamStyle(r.index)}
                className="grid grid-cols-[auto_1fr_auto] items-center gap-x-3 gap-y-1.5"
              >
                <span className="text-muted-foreground w-6 text-sm font-semibold tabular-nums">
                  {r.rank}
                  <span className="sr-only">{r.tied ? ' (tied)' : ''}</span>
                </span>
                <span className="flex min-w-0 items-center gap-2 text-sm">
                  <span aria-hidden className="border-border bg-background grid size-6 shrink-0 place-items-center rounded-full border-2 border-(--team) text-xs font-semibold">
                    {teamMark(r.index)}
                  </span>
                  <span className={cn('truncate', r.id === mine && 'font-semibold')}>{r.name}</span>
                  <span className="text-muted-foreground shrink-0 text-xs">{(L.size ?? SIZE)(r.size)}</span>
                </span>
                <span className="text-end text-sm font-semibold tabular-nums">
                  <span aria-hidden>{fmt.format(value)}</span>
                  <span className="sr-only">{(L.points ?? ((n: number, b) => (b === 'average' ? `${n} per player` : `${n} points`)))(value, by)}</span>
                  {r.gained > 0 ? (
                    <span className="text-muted-foreground ms-1.5 text-xs font-medium">{(L.gained ?? ((n: number) => `+${n}`))(r.gained)}</span>
                  ) : null}
                </span>
                <span aria-hidden className="bg-muted col-span-3 block h-2 overflow-hidden rounded-full">
                  <span
                    data-slot="team-scoreboard-bar"
                    className={cn(
                      'block h-full origin-left rounded-full bg-(--team) rtl:origin-right',
                      reduced ? '' : 'transition-[width] duration-(--duration-slow) ease-enter',
                    )}
                    style={{ width: `${top > 0 ? Math.max(2, Math.round((value / top) * 100)) : 0}%` }}
                  />
                </span>
              </li>
            );
          })}
        </ol>
      ) : (
        <p data-slot="team-scoreboard-empty" className="text-muted-foreground">
          {L.empty ?? 'No teams yet.'}
        </p>
      )}
      <span data-slot="team-scoreboard-announce" aria-live="polite" className="sr-only">
        {announce}
      </span>
    </section>
  );
}
TeamScoreboard.displayName = 'TeamScoreboard';

// --- TeamBadge ------------------------------------------------------------------

export interface TeamBadgeLabels {
  /** @default (team) => `You are on ${team}` */
  on?: (team: string) => string;
  /** @default 'Waiting for a team' */
  none?: string;
  /** @default (mark) => `Team ${mark}` */
  mark?: (mark: string) => string;
}

type TeamBadgeProps = Omit<React.ComponentProps<'div'>, 'children'> & {
  room: Pick<RoomState, 'shared' | 'players'> | null;
  /** The viewer's player id. */
  selfId: string;
  labels?: TeamBadgeLabels;
};

function TeamBadge({ room, selfId, labels, className, ...props }: TeamBadgeProps) {
  const L = labels ?? {};
  const teams = readTeams(room);
  const team = teams ? teamOf(teams, selfId) : null;
  const index = teams && team ? teams.teams.findIndex((t) => t.id === team.id) : 0;
  return (
    <div
      role="status"
      data-slot="team-badge"
      data-state={team ? 'team' : 'none'}
      data-team-id={team?.id}
      data-min-viewport={String(MIN_VIEWPORT)}
      style={team ? teamStyle(index) : undefined}
      className={cn(
        'bg-card text-card-foreground border-border flex items-center gap-3 rounded-xl border border-s-4 p-4',
        team ? 'border-s-(--team)' : 'border-dashed',
        className,
      )}
      {...props}
    >
      {team ? (
        <>
          <span
            aria-hidden
            className="border-border bg-background grid size-9 shrink-0 place-items-center rounded-full border-2 border-(--team) text-base font-semibold"
          >
            {teamMark(index)}
          </span>
          <span className="min-w-0 text-lg font-semibold break-words">{(L.on ?? ((n: string) => `You are on ${n}`))(team.name)}</span>
        </>
      ) : (
        <span className="text-muted-foreground">{L.none ?? 'Waiting for a team'}</span>
      )}
    </div>
  );
}
TeamBadge.displayName = 'TeamBadge';

export { TeamBadge, TeamBoard, TeamScoreboard };
export type { TeamBadgeProps, TeamBoardProps, TeamScoreboardProps };

export type Random = () => number;

/**
 * A repeatable random source (mulberry32): the same seed gives the same run. For tests, and for a
 * host that wants a split it can reproduce.
 */
export function seededRandom(seed: number): Random {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A shuffled copy (Fisher-Yates). A `random` that returns 1 or more is held below 1. */
export function shuffled<T>(items: readonly T[], random: Random = Math.random): T[] {
  const out = items.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.min(i, Math.floor(random() * (i + 1)));
    [out[i], out[j]] = [out[j] as T, out[i] as T];
  }
  return out;
}

/**
 * Deals `items` into `groups` piles, first to last then back (1 2 3 3 2 1 …), so when the items
 * are sorted best first every pile gets its share of the best, and no pile is more than one
 * larger than another.
 */
export function snakeDeal<T>(items: readonly T[], groups: number): T[][] {
  const piles: T[][] = Array.from({ length: groups }, () => []);
  items.forEach((item, i) => {
    const pos = i % groups;
    (piles[Math.floor(i / groups) % 2 === 0 ? pos : groups - 1 - pos] as T[]).push(item);
  });
  return piles;
}

/** The index of the smallest size, the first on a tie. -1 for no sizes. */
export function smallestIndex(sizes: readonly number[]): number {
  let best = -1;
  sizes.forEach((size, i) => {
    if (best === -1 || size < (sizes[best] as number)) best = i;
  });
  return best;
}

/** Clamps a count to a whole number in [min, max]; NaN falls to `min`. */
export function clampCount(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, Math.floor(Number.isFinite(value) ? value : min)));
}

/** True for a plain JSON object (not null, not an array). */
export const isRecord = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v);

/** An id read from untrusted data: a short word of letters, digits, `_` and `-`. */
export const isId = (v: unknown): v is string => typeof v === 'string' && /^[\w-]{1,64}$/.test(v);

/**
 * @interlace/ui — games/group-model
 *
 * The small, pure helpers every way of splitting a room shares (teams, breakout groups, pairs):
 * a shuffle that takes its random source, a fair deal, and a seeded random for tests and replays.
 * Nothing here knows about a room.
 */

/** A float in [0, 1), like `Math.random`. */

export interface LeaderboardEntry {
  /** Stable id: a player or a group. */
  id: string;
  /** What the board shows. */
  name: string;
  score: number;
  /** Breaks ties on score: lower first (time taken, say). Equal or missing values share a rank. */
  tiebreak?: number;
}

export interface RankedEntry extends LeaderboardEntry {
  /** 1-based; ties share a rank and the next rank skips (1, 2, 2, 4). */
  rank: number;
  /** True when another entry has the same rank. */
  tied: boolean;
}

export interface RankOptions {
  /** `desc` when a higher score wins. @default 'desc' */
  order?: 'desc' | 'asc';
  /** Below this many entries the board is hidden. @default 1 */
  minPlayers?: number;
  /** Rows to show from the top. @default all */
  limit?: number;
  /** The viewing player's id: their row is kept even outside `limit`. */
  currentId?: string;
}

export interface RankedBoard {
  /** False while fewer than `minPlayers` have played. */
  visible: boolean;
  /** Entries counted. */
  players: number;
  /** The top rows, within `limit`. Empty while hidden. */
  top: RankedEntry[];
  /** The viewing player's row when it falls outside `top`. */
  current?: RankedEntry;
}

/** Rank every entry. */
export function rankEntries(entries: readonly LeaderboardEntry[], order: 'desc' | 'asc' = 'desc'): RankedEntry[] {
  const sign = order === 'desc' ? -1 : 1;
  const sorted = entries
    .slice()
    .sort(
      (a, b) =>
        sign * (a.score - b.score) || (a.tiebreak ?? Infinity) - (b.tiebreak ?? Infinity) || a.name.localeCompare(b.name),
    );
  const same = (a: LeaderboardEntry, b: LeaderboardEntry) => a.score === b.score && (a.tiebreak ?? null) === (b.tiebreak ?? null);
  const ranked: RankedEntry[] = [];
  sorted.forEach((entry, i) => {
    const prev = sorted[i - 1];
    const rank = prev && same(prev, entry) ? (ranked[i - 1] as RankedEntry).rank : i + 1;
    ranked.push({ ...entry, rank, tied: false });
  });
  for (let i = 0; i < ranked.length; i++) {
    const r = ranked[i] as RankedEntry;
    r.tied = ranked[i - 1]?.rank === r.rank || ranked[i + 1]?.rank === r.rank;
  }
  return ranked;
}

/** The board as a page shows it: hidden below the minimum, top rows, and the viewer's own row. */
export function buildBoard(entries: readonly LeaderboardEntry[], options: RankOptions = {}): RankedBoard {
  const { order = 'desc', minPlayers = 1, limit, currentId } = options;
  const players = entries.length;
  if (players < Math.max(1, minPlayers)) return { visible: false, players, top: [] };
  const ranked = rankEntries(entries, order);
  const top = limit === undefined ? ranked : ranked.slice(0, limit);
  const mine = currentId === undefined ? undefined : ranked.find((e) => e.id === currentId);
  const current = mine && !top.includes(mine) ? mine : undefined;
  return { visible: true, players, top, current };
}

/**
 * @interlace/ui — games/leaderboard-model
 *
 * Ranking for a group's board: ties share a rank (1, 2, 2, 4), the board
 * stays hidden until enough people have played, and the player's own row is
 * found even when it falls outside the top rows. Pure, so the server that
 * stores scores ranks them the same way.
 *
 * ## Why a minimum
 *
 * A board of two people tells each of them exactly what the other scored.
 * `minPlayers` keeps a small group's scores private until there are enough
 * of them to stand in a crowd.
 */

import { rankEntries, type RankedEntry } from '@/components/ui/games/leaderboard-model';

/**
 * @interlace/ui — games/room-model
 *
 * The pure core of a live room: one host on a big screen, players on their
 * phones, a join code, a lobby, rounds and a podium. Every client runs the
 * same reducer, so the host's screen and every phone agree on what happens,
 * and a server can replay a room from its events.
 *
 * The host is the authority. Players send intents (join, leave, answer); the
 * host applies them with `applyRoomEvent`, which refuses anything the sender
 * may not do, and sends the new state to everyone. How messages travel is a
 * `RoomTransport`: two functions, so any realtime service fits behind it. The
 * kit ships an in-memory hub (tests, demos, one screen) and a
 * BroadcastChannel transport (tabs on one device); a WebSocket or hosted
 * realtime adapter is a few lines in the app.
 *
 * Time is always a timestamp in ms from the host's clock (`startsAt`,
 * `endsAt`), so a phone that joins late counts down to the same moment.
 */

// --- Join codes -----------------------------------------------------------------

/** Letters and digits no one misreads: no 0/O, 1/I/L, or U/V. */
export const JOIN_CODE_ALPHABET = '23456789ABCDEFGHJKMNPQRSTWXYZ';

export interface JoinCodeOptions {
  /** @default 6 */
  length?: number;
  /** @default JOIN_CODE_ALPHABET. Pass '0123456789' for a numeric PIN. */
  alphabet?: string;
}

/**
 * A new join code. Leave `random` out to draw from `crypto.getRandomValues`
 * without bias (rejection sampling on a bit mask); pass a function returning
 * a float in [0, 1) for seeded tests. The alphabet holds at most 256 characters.
 */
export function makeJoinCode(options: JoinCodeOptions = {}, random?: () => number): string {
  const { length = 6, alphabet = JOIN_CODE_ALPHABET } = options;
  const n = alphabet.length;
  if (n < 1 || n > 256) throw new RangeError('A join code alphabet holds 1 to 256 characters.');
  const crypto = (globalThis as { crypto?: Crypto }).crypto;
  let code = '';
  if (!random && crypto?.getRandomValues) {
    const mask = 2 ** Math.ceil(Math.log2(n)) - 1;
    while (code.length < length) {
      for (const byte of crypto.getRandomValues(new Uint8Array(length * 2))) {
        const index = byte & mask;
        if (index < n && code.length < length) code += alphabet[index];
      }
    }
    return code;
  }
  const pick = random ?? Math.random;
  for (let i = 0; i < length; i++) code += alphabet[Math.min(n - 1, Math.floor(pick() * n))];
  return code;
}

/**
 * What someone typed, as a code: upper case, spaces and dashes dropped.
 * Returns null when it has the wrong length or a character outside the
 * alphabet, so the field can say so before anything is sent.
 */
export function normalizeJoinCode(input: string, options: JoinCodeOptions = {}): string | null {
  const { length = 6, alphabet = JOIN_CODE_ALPHABET } = options;
  const code = input.toUpperCase().replace(/[\s\-–—.]/g, '');
  if (code.length !== length) return null;
  for (const ch of code) if (!alphabet.includes(ch)) return null;
  return code;
}

/** A code in groups for reading aloud and on a big screen: "K7Q 4MZ". */
export function formatJoinCode(code: string, group = 3): string {
  if (group <= 0) return code;
  const parts: string[] = [];
  for (let i = 0; i < code.length; i += group) parts.push(code.slice(i, i + group));
  return parts.join(' ');
}

// --- State ----------------------------------------------------------------------

export type RoomPhase = 'lobby' | 'countdown' | 'question' | 'reveal' | 'podium' | 'closed';

export interface RoomPlayer {
  id: string;
  name: string;
  /** False after `leave`; the player keeps their score and can come back. */
  connected: boolean;
}

export interface RoomState {
  code: string;
  hostId: string;
  phase: RoomPhase;
  /** No new players while locked. Players already in can still reconnect. */
  locked: boolean;
  /**
   * When the join code stops letting new players in, in ms (host clock), or
   * null for a code that lasts as long as the room. Players already in can
   * still reconnect after it.
   */
  codeExpiresAt: number | null;
  /** In the order they joined. */
  players: RoomPlayer[];
  /** Players the host removed; they cannot join again with the same id. */
  removed: string[];
  /** 0 in the lobby, then 1, 2, 3… */
  round: number;
  /** How many rounds the game has, when known. */
  rounds: number | null;
  /** When the countdown ends, in ms (host clock). */
  startsAt: number | null;
  /** When the current question closes, in ms (host clock). null: no clock. */
  endsAt: number | null;
  /**
   * What the current round asks, as the host sent it with `question`: whatever
   * the game needs (a prompt and its choices, a number to guess). Every phone
   * and a player who joins late see the same round. null in the lobby.
   * Keep the answer out of it until `reveal`.
   */
  prompt: unknown;
  /** The round's answer, as the host sent it with `reveal`. null until then. */
  solution: unknown;
  /** Total points per player id. */
  scores: Record<string, number>;
  /** This round's answers per player id. Cleared when a new round starts. */
  answers: Record<string, RoomAnswer>;
  /** Points each player won in the last revealed round. */
  lastPoints: Record<string, number>;
  /**
   * Room-wide extras the host shares with every screen, by name: team assignments, breakout
   * groups, pairs (see `team-model`, `breakout-model`, `pair-model`). They ride in the room, so
   * they inherit its guarantees: the newest `seq` wins, a late joiner and a phone that reconnects
   * get them with the state, and a host that restores the room (`restoreRoom`) restores them.
   * Written by the host's `share` event; read with `readShared`, which treats them as untrusted.
   * Absent until the first `share`.
   */
  shared?: Record<string, unknown>;
  /**
   * The ids of each player's most recent `submit` events, so a message the network delivers twice
   * (or a player's own resend) is applied once, and a player can see theirs was taken.
   */
  acked?: Record<string, string[]>;
  /** Bumped on every change, so a client keeps only the newest state. */
  seq: number;
}

export interface RoomAnswer {
  value: unknown;
  /**
   * When it reached the host, in ms (host clock). `useRoom` stamps it on
   * arrival, so a player cannot claim an earlier answer than they gave.
   */
  at: number;
}

/** Why an activity refuses a move. */
export type ActivityRefusal = 'not-host' | 'wrong-phase' | 'full' | 'rate-limited' | 'bad-action';

export interface ActivityContext {
  /** Who made the move: a player's id, or the host's. */
  playerId: string;
  /** True when the host made it. */
  host: boolean;
  /** When it arrived, in ms (host clock). */
  at: number;
  /** Everyone in the room now. */
  players: readonly RoomPlayer[];
}

/**
 * An activity's rule: its slice of `RoomState.shared` (anything, or null before it starts: read it
 * as untrusted), one move, and who made it. Returns the new slice (null removes it) or why not.
 * Pure: the host runs it to decide and again to apply, so it must give the same answer twice.
 */
export type ActivityReducer = (
  slice: unknown,
  action: unknown,
  ctx: ActivityContext,
) => { slice: unknown } | { refuse: ActivityRefusal };

export interface RoomSettings {
  /** The activities this room runs, by the key of their slice. */
  activities?: Record<string, ActivityReducer>;
  /** The most players the room takes. @default 200 */
  maxPlayers?: number;
  /** The longest name, in characters. @default 24 */
  maxNameLength?: number;
}

export function createRoom(init: {
  code: string;
  hostId: string;
  rounds?: number | null;
  /** When the code stops admitting new players, in ms (host clock). */
  codeExpiresAt?: number | null;
}): RoomState {
  return {
    code: init.code,
    hostId: init.hostId,
    phase: 'lobby',
    locked: false,
    codeExpiresAt: init.codeExpiresAt ?? null,
    players: [],
    removed: [],
    round: 0,
    rounds: init.rounds ?? null,
    startsAt: null,
    endsAt: null,
    prompt: null,
    solution: null,
    scores: {},
    answers: {},
    lastPoints: {},
    seq: 0,
  };
}

// --- Events ---------------------------------------------------------------------

/** Events a player sends about themselves. */
export type RoomPlayerEvent =
  | {
      type: 'join';
      playerId: string;
      name: string;
      /**
       * When the join arrived, in ms. `useRoom` stamps it with the host's clock,
       * so an expired code cannot be beaten by a phone with its clock set back;
       * code that calls `applyRoomEvent` directly must stamp it too. While the
       * room has an expiry, an unstamped new join is refused as `expired`.
       */
      at?: number;
    }
  | { type: 'leave'; playerId: string }
  /**
   * A player's move in an activity that takes input from everyone (a question, a vote, a reaction, a
   * raised hand, a spot on a line). `key` names the activity (`RoomState.shared[key]`), `action` is
   * what it takes, and `id` is unique per move: the host applies a move once however often it
   * arrives. The host may send one too (`playerId` its own id), for what only it may do. Which
   * moves an activity allows is its reducer's rule (`RoomSettings.activities`).
   */
  | {
      type: 'submit';
      playerId: string;
      id: string;
      key: string;
      action: unknown;
      /**
       * When it arrived, in ms (host clock). `useRoom` stamps it; code that calls `applyRoomEvent`
       * directly must too. A `submit` without it is refused.
       */
      at?: number;
      /** Send it again until the host's state shows it. @default true. Off for moves that go stale (a reaction). */
      retry?: boolean;
    }
  | {
      type: 'answer';
      playerId: string;
      value: unknown;
      /**
       * When the answer arrived. `useRoom` replaces it with the host's clock on
       * receipt; code that calls `applyRoomEvent` directly must do the same
       * rather than trust the sender's value.
       */
      at: number;
    };

/** Events only the host sends. */
export type RoomHostEvent =
  | { type: 'lock'; locked: boolean }
  /** Moves the code's expiry: later to let latecomers in, null for no expiry. */
  | { type: 'extend-code'; expiresAt: number | null }
  | { type: 'remove'; playerId: string }
  /** Starts the countdown to the first round (or the next one). */
  | { type: 'countdown'; startsAt: number }
  /** Opens a round. `endsAt` null for no clock. `prompt`: what the round asks (see `RoomState.prompt`). */
  | { type: 'question'; endsAt: number | null; prompt?: unknown }
  /** Closes the round and adds each player's points. `solution`: the round's answer, for every screen. */
  | { type: 'reveal'; points: Record<string, number>; solution?: unknown }
  | { type: 'podium' }
  | { type: 'close' }
  /** Back to the lobby with the same players, scores at zero and the room open again. */
  | { type: 'restart' }
  /** Sets one named extra for every screen (`RoomState.shared`); `value` null removes it. */
  | { type: 'share'; key: string; value: unknown };

export type RoomEvent = RoomPlayerEvent | RoomHostEvent;

export type RoomRejection =
  | 'not-host'
  | 'not-you'
  | 'closed'
  | 'locked'
  | 'expired'
  | 'full'
  | 'removed'
  | 'name-empty'
  | 'name-taken'
  | 'wrong-phase'
  | 'already-answered'
  | 'unknown-player'
  /** A `share` with a key that is not a short lowercase name, or a value that is not JSON or too big. */
  | 'bad-share'
  /** A `submit` for an activity this room does not run. */
  | 'unknown-activity'
  /** A `submit` the activity cannot take (nonsense, or not allowed now). */
  | 'bad-action'
  /** A `submit` with an id the host already applied: said nothing to, never counted twice. */
  | 'duplicate'
  /** Too many moves too fast from this player, or from the room. */
  | 'rate-limited';

const HOST_EVENTS = new Set<RoomEvent['type']>([
  'lock',
  'extend-code',
  'remove',
  'countdown',
  'question',
  'reveal',
  'podium',
  'close',
  'restart',
  'share',
]);

/** Names of `shared` entries: lowercase, digits and dashes, so no key can be `__proto__`. */
const SHARE_KEY = /^[a-z][a-z0-9-]{0,31}$/;
/** The most a room's extras may weigh as JSON, in characters: every state message carries them. */
export const MAX_SHARED_SIZE = 60_000;

/** Which phases each host step may follow. */
const NEXT: Partial<Record<RoomEvent['type'], readonly RoomPhase[]>> = {
  countdown: ['lobby', 'reveal'],
  question: ['countdown', 'reveal'],
  reveal: ['question'],
  podium: ['reveal', 'question'],
  restart: ['podium', 'reveal', 'question', 'countdown', 'lobby'],
};

/**
 * True when a join at `at` (host clock) comes after the code stopped admitting new players.
 * Fails closed: when the room has an expiry, a join without `at` counts as expired, so a server
 * that forgets to stamp joins cannot let people in late. Stamp `join.at` with the host clock.
 */
export function codeExpired(state: Pick<RoomState, 'codeExpiresAt'>, at: number | undefined): boolean {
  if (state.codeExpiresAt === null) return false;
  return at === undefined || at >= state.codeExpiresAt;
}

/** A display name, trimmed, inner spaces collapsed, and cut to `max` characters. */
export function cleanName(name: string, max = 24): string {
  return Array.from(name.trim().replace(/\s+/g, ' ')).slice(0, max).join('').trim();
}

const sameName = (a: string, b: string) => a.localeCompare(b, undefined, { sensitivity: 'base' }) === 0;

/** How many ids of a player's `submit` moves the room remembers. */
export const ACK_KEEP = 16;

type SubmitEvent = Extract<RoomEvent, { type: 'submit' }>;

/** What a `submit` would do, or why it may not: the same call decides and applies. */
function runSubmit(
  state: RoomState,
  event: SubmitEvent,
  settings: RoomSettings,
): { slice: unknown } | { refuse: RoomRejection } {
  if (event.playerId !== state.hostId && !state.players.some((p) => p.id === event.playerId))
    return { refuse: 'unknown-player' };
  if (typeof event.id !== 'string' || !event.id || event.id.length > 64 || typeof event.at !== 'number' || !Number.isFinite(event.at))
    return { refuse: 'bad-action' };
  if (Object.hasOwn(state.acked ?? {}, event.playerId) && (state.acked as Record<string, string[]>)[event.playerId]!.includes(event.id))
    return { refuse: 'duplicate' };
  const reducer = SHARE_KEY.test(event.key) && settings.activities && Object.hasOwn(settings.activities, event.key) ? settings.activities[event.key] : undefined;
  if (!reducer) return { refuse: 'unknown-activity' };
  const slice = state.shared && Object.hasOwn(state.shared, event.key) ? state.shared[event.key] : null;
  let result: ReturnType<ActivityReducer>;
  try {
    result = reducer(slice, event.action, { playerId: event.playerId, host: event.playerId === state.hostId, at: event.at, players: state.players });
  } catch {
    return { refuse: 'bad-action' };
  }
  if ('refuse' in result) return result;
  const json = JSON.stringify(result.slice ?? null);
  return json === undefined || json.length > MAX_SHARED_SIZE ? { refuse: 'full' } : result;
}

function rejectSubmit(state: RoomState, event: SubmitEvent, settings: RoomSettings): RoomRejection | null {
  const result = runSubmit(state, event, settings);
  return 'refuse' in result ? result.refuse : null;
}

/**
 * Why `from` may not apply `event` to `state`, or null when they may. The
 * host's own id may send any event; a player may send only their own.
 */
export function rejectRoomEvent(
  state: RoomState,
  event: RoomEvent,
  from: string,
  settings: RoomSettings = {},
): RoomRejection | null {
  const isHost = from === state.hostId;
  if (HOST_EVENTS.has(event.type)) {
    if (!isHost) return 'not-host';
  } else if (!isHost && (event as RoomPlayerEvent).playerId !== from) {
    return 'not-you';
  }
  if (state.phase === 'closed') return 'closed';

  const allowed = NEXT[event.type];
  if (allowed && !allowed.includes(state.phase)) return 'wrong-phase';

  switch (event.type) {
    case 'join': {
      if (state.removed.includes(event.playerId)) return 'removed';
      const name = cleanName(event.name, settings.maxNameLength);
      if (!name) return 'name-empty';
      const known = state.players.find((p) => p.id === event.playerId);
      if (state.players.some((p) => p.id !== event.playerId && sameName(p.name, name))) return 'name-taken';
      if (known) return null; // a reconnect, even when locked
      if (state.locked) return 'locked';
      if (codeExpired(state, event.at)) return 'expired';
      if (state.players.length >= (settings.maxPlayers ?? 200)) return 'full';
      return null;
    }
    case 'leave':
      return state.players.some((p) => p.id === event.playerId) ? null : 'unknown-player';
    case 'answer':
      if (state.phase !== 'question') return 'wrong-phase';
      if (!state.players.some((p) => p.id === event.playerId)) return 'unknown-player';
      if (event.playerId in state.answers) return 'already-answered';
      return null;
    case 'remove':
      return state.players.some((p) => p.id === event.playerId) ? null : 'unknown-player';
    case 'submit':
      return rejectSubmit(state, event, settings);
    case 'share': {
      if (!SHARE_KEY.test(event.key)) return 'bad-share';
      const json = JSON.stringify(event.value);
      return json === undefined || json.length > MAX_SHARED_SIZE ? 'bad-share' : null;
    }
    default:
      return null;
  }
}

/**
 * The room after `event` from `from`. Returns the same object when the
 * event is refused (see `rejectRoomEvent`), so `next === state` means
 * nothing happened.
 */
export function applyRoomEvent(
  state: RoomState,
  event: RoomEvent,
  from: string,
  settings: RoomSettings = {},
): RoomState {
  if (rejectRoomEvent(state, event, from, settings)) return state;
  const next = (patch: Partial<RoomState>): RoomState => ({
    ...state,
    ...patch,
    seq: state.seq + 1,
  });

  switch (event.type) {
    case 'join': {
      const name = cleanName(event.name, settings.maxNameLength);
      const known = state.players.some((p) => p.id === event.playerId);
      return next({
        players: known
          ? state.players.map((p) => (p.id === event.playerId ? { ...p, name, connected: true } : p))
          : [...state.players, { id: event.playerId, name, connected: true }],
        scores: known ? state.scores : { ...state.scores, [event.playerId]: 0 },
      });
    }
    case 'leave':
      return next({
        players: state.players.map((p) => (p.id === event.playerId ? { ...p, connected: false } : p)),
      });
    case 'answer':
      return next({
        answers: {
          ...state.answers,
          [event.playerId]: { value: event.value, at: event.at },
        },
      });
    case 'lock':
      return next({ locked: event.locked });
    case 'extend-code':
      return next({ codeExpiresAt: event.expiresAt });
    case 'remove': {
      const { [event.playerId]: _score, ...scores } = state.scores;
      const { [event.playerId]: _answer, ...answers } = state.answers;
      const { [event.playerId]: _acks, ...acked } = state.acked ?? {};
      return next({
        acked,
        players: state.players.filter((p) => p.id !== event.playerId),
        removed: [...state.removed, event.playerId],
        scores,
        answers,
      });
    }
    case 'countdown':
      return next({
        phase: 'countdown',
        startsAt: event.startsAt,
        endsAt: null,
      });
    case 'question':
      return next({
        phase: 'question',
        round: state.round + 1,
        endsAt: event.endsAt,
        prompt: event.prompt ?? null,
        solution: null,
        answers: {},
        lastPoints: {},
      });
    case 'reveal': {
      const scores = { ...state.scores };
      const lastPoints: Record<string, number> = {};
      for (const p of state.players) {
        const won = Number.isFinite(event.points[p.id]) ? event.points[p.id]! : 0;
        lastPoints[p.id] = won;
        scores[p.id] = (scores[p.id] ?? 0) + won;
      }
      return next({ phase: 'reveal', scores, lastPoints, endsAt: null, solution: event.solution ?? null });
    }
    case 'podium':
      return next({ phase: 'podium', endsAt: null });
    case 'close':
      return next({
        phase: 'closed',
        locked: true,
        startsAt: null,
        endsAt: null,
      });
    case 'submit': {
      const result = runSubmit(state, event, settings) as { slice: unknown };
      const { [event.key]: _old, ...rest } = state.shared ?? {};
      const mine = Object.hasOwn(state.acked ?? {}, event.playerId) ? (state.acked as Record<string, string[]>)[event.playerId]! : [];
      return next({
        shared: result.slice === null ? rest : { ...rest, [event.key]: result.slice },
        acked: { ...state.acked, [event.playerId]: [...mine, event.id].slice(-ACK_KEEP) },
      });
    }
    case 'share': {
      const { [event.key]: _old, ...rest } = state.shared ?? {};
      return next({ shared: event.value === null ? rest : { ...rest, [event.key]: event.value } });
    }
    case 'restart':
      return next({
        phase: 'lobby',
        locked: false,
        round: 0,
        startsAt: null,
        endsAt: null,
        prompt: null,
        solution: null,
        answers: {},
        lastPoints: {},
        scores: Object.fromEntries(state.players.map((p) => [p.id, 0])),
      });
  }
}

// --- Guessing codes -------------------------------------------------------------

/*
 * Stops people guessing their way into a room. Every wrong code counts
 * against where it came from (a network, a device, whatever key your server
 * trusts) and against the room as a whole; past either limit, more tries are
 * refused until the window moves on. A six-character code from
 * `makeJoinCode` has about 600 million values, so five tries per source and
 * thirty per room leave a guesser nowhere, while a person who mistyped twice
 * is never stopped. Pure and serialisable: keep the state wherever the code
 * is checked (a server, an edge function, the host), call `checkJoinAttempt`
 * before comparing the code and `recordJoinAttempt` after.
 */

export interface JoinGuardOptions {
  /** Wrong tries one source may make in the window. @default 5 */
  perSource?: number;
  /** Wrong tries the whole room accepts in the window, across sources. @default 30 */
  total?: number;
  /** How far back wrong tries count, in ms. @default 10 minutes */
  windowMs?: number;
}

export interface JoinGuardState {
  /** Wrong tries, oldest first. */
  failures: { source: string; at: number }[];
}

export type JoinGuardVerdict =
  | { allowed: true; left: number }
  | {
      allowed: false;
      /** `source`: this source used its tries. `room`: the room stopped taking guesses. */
      reason: 'source' | 'room';
      /** When the oldest counted try leaves the window and one more is allowed, in ms. */
      retryAt: number;
    };

const DEFAULTS = { perSource: 5, total: 30, windowMs: 10 * 60_000 };

const settings = (o: JoinGuardOptions) => ({
  perSource: Math.max(1, Math.floor(o.perSource ?? DEFAULTS.perSource)),
  total: Math.max(1, Math.floor(o.total ?? DEFAULTS.total)),
  windowMs: Math.max(1, o.windowMs ?? DEFAULTS.windowMs),
});

export function createJoinGuard(): JoinGuardState {
  return { failures: [] };
}

/** Drops wrong tries older than the window. */
export function pruneJoinGuard(state: JoinGuardState, now: number, options: JoinGuardOptions = {}): JoinGuardState {
  const { windowMs } = settings(options);
  const failures = state.failures.filter((f) => now - f.at < windowMs);
  return failures.length === state.failures.length ? state : { failures };
}

/** May `source` try a code now? Ask before comparing the code, so a blocked source learns nothing. */
export function checkJoinAttempt(
  state: JoinGuardState,
  source: string,
  now: number,
  options: JoinGuardOptions = {},
): JoinGuardVerdict {
  const { perSource, total, windowMs } = settings(options);
  const recent = pruneJoinGuard(state, now, options).failures;
  const mine = recent.filter((f) => f.source === source);
  if (recent.length >= total) {
    return { allowed: false, reason: 'room', retryAt: recent[recent.length - total]!.at + windowMs };
  }
  if (mine.length >= perSource) {
    return { allowed: false, reason: 'source', retryAt: mine[mine.length - perSource]!.at + windowMs };
  }
  return { allowed: true, left: Math.min(perSource - mine.length, total - recent.length) };
}

/** The guard after a try: a wrong code is counted, a right one changes nothing. */
export function recordJoinAttempt(
  state: JoinGuardState,
  source: string,
  correct: boolean,
  now: number,
  options: JoinGuardOptions = {},
): JoinGuardState {
  const pruned = pruneJoinGuard(state, now, options);
  return correct ? pruned : { failures: [...pruned.failures, { source, at: now }] };
}

// --- Reading the state ----------------------------------------------------------

/**
 * How far the host's clock is ahead of this one, in ms, from `{ at, local }` pairs: the host's
 * send time and this client's receive time. A message can only arrive after it was sent, so each
 * `at - local` is a lower bound on the true offset and the largest is the closest. Pass the recent
 * samples only, so a host whose clock is reset is followed. 0 with no samples.
 */
export function clockOffset(samples: readonly { at: number; local: number }[]): number {
  let best = -Infinity;
  for (const s of samples) if (Number.isFinite(s.at) && Number.isFinite(s.local)) best = Math.max(best, s.at - s.local);
  return best === -Infinity ? 0 : best;
}

/** Players still connected. */
export function connectedPlayers(state: RoomState): RoomPlayer[] {
  return state.players.filter((p) => p.connected);
}

/** How many connected players have answered this round, of how many. */
export function answerProgress(state: RoomState): {
  answered: number;
  total: number;
} {
  const live = connectedPlayers(state);
  return {
    answered: live.filter((p) => p.id in state.answers).length,
    total: live.length,
  };
}

/** Everyone in the room by score, ties sharing a rank (the leaderboard's ranking). */
export function roomStandings(state: RoomState): RankedEntry[] {
  return rankEntries(
    state.players.map((p) => ({
      id: p.id,
      name: p.name,
      score: state.scores[p.id] ?? 0,
    })),
  );
}

/**
 * One named extra from `RoomState.shared`, read as untrusted: `decode` gets whatever is there
 * (anything, from an older version of the app or a bad client) and returns the value or null.
 * Null too when it is absent, or when `decode` throws, so a screen shows "nothing set" rather
 * than breaking.
 */
export function readShared<T>(
  state: Pick<RoomState, 'shared'> | null | undefined,
  key: string,
  decode: (raw: unknown) => T | null,
): T | null {
  const shared = state?.shared;
  if (!shared || !Object.hasOwn(shared, key)) return null;
  try {
    return decode(shared[key]);
  } catch {
    return null;
  }
}

// --- Keeping a room across a refresh -------------------------------------------------

/**
 * How far `restoreRoom` moves `seq` ahead. A host that restores a save written just before its
 * last few changes would otherwise send states the phones already hold newer ones of, and every
 * phone would ignore them.
 */
export const RESTORE_SEQ_JUMP = 1_000;

const PHASES: readonly RoomPhase[] = ['lobby', 'countdown', 'question', 'reveal', 'podium', 'closed'];

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const isNum = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
const nullableNum = (v: unknown): number | null | undefined => (v === null ? null : isNum(v) ? v : undefined);
const isCount = (v: unknown): v is number => isNum(v) && Number.isInteger(v) && v >= 0;

/** A record read from JSON, as plain own properties (a `__proto__` key stays data), values checked. */
function cleanRecord<T>(raw: unknown, ok: (v: unknown) => T | undefined): Record<string, T> {
  const out: [string, T][] = [];
  if (isRecord(raw)) {
    for (const [k, v] of Object.entries(raw)) {
      const value = ok(v);
      if (value !== undefined) out.push([k, value]);
    }
  }
  return Object.fromEntries(out);
}

/** The room as text, to keep in `localStorage` or on a server, so a host that refreshes can go on. */
export function serializeRoom(state: RoomState): string {
  return JSON.stringify(state);
}

/**
 * The room from text written by `serializeRoom`, or null when it is not one (absent, damaged, from
 * another host). Everything is checked and rebuilt, never trusted. Nobody is known to be here yet:
 * each player comes back `away`, and a phone that is still open says so by itself (it sees itself
 * away and joins again), so the host never shows someone present who left while it was down.
 * Scores, answers, rounds, clocks and the room's extras are kept, and `seq` moves ahead by
 * `RESTORE_SEQ_JUMP` so phones take the restored state as the newest.
 *
 * Pass `hostId` to refuse a room saved by someone else.
 */
export function restoreRoom(text: string | null | undefined, options: { hostId?: string } = {}): RoomState | null {
  if (!text) return null;
  let raw: unknown;
  try {
    raw = JSON.parse(text);
  } catch {
    return null;
  }
  if (!isRecord(raw)) return null;
  const { code, hostId, phase, players, seq, round } = raw;
  if (typeof code !== 'string' || !code || typeof hostId !== 'string' || !hostId) return null;
  if (options.hostId !== undefined && hostId !== options.hostId) return null;
  if (!PHASES.includes(phase as RoomPhase) || !Array.isArray(players) || !isCount(seq) || !isCount(round)) return null;
  const seen = new Set<string>();
  const kept: RoomPlayer[] = [];
  for (const p of players) {
    if (!isRecord(p) || typeof p.id !== 'string' || typeof p.name !== 'string') return null;
    if (seen.has(p.id)) continue;
    seen.add(p.id);
    kept.push({ id: p.id, name: p.name, connected: false });
  }
  const rounds = raw.rounds === null || raw.rounds === undefined ? null : isCount(raw.rounds) ? raw.rounds : undefined;
  const startsAt = nullableNum(raw.startsAt ?? null);
  const endsAt = nullableNum(raw.endsAt ?? null);
  const codeExpiresAt = nullableNum(raw.codeExpiresAt ?? null);
  if (rounds === undefined || startsAt === undefined || endsAt === undefined || codeExpiresAt === undefined) return null;
  const num = (v: unknown) => (isNum(v) ? v : undefined);
  const answer = (v: unknown) => (isRecord(v) && isNum(v.at) ? { value: v.value, at: v.at } : undefined);
  const state: RoomState = {
    code,
    hostId,
    phase: phase as RoomPhase,
    locked: raw.locked === true,
    codeExpiresAt,
    players: kept,
    removed: Array.isArray(raw.removed) ? raw.removed.filter((id): id is string => typeof id === 'string') : [],
    round,
    rounds,
    startsAt,
    endsAt,
    prompt: raw.prompt ?? null,
    solution: raw.solution ?? null,
    scores: cleanRecord(raw.scores, num),
    answers: cleanRecord(raw.answers, answer),
    lastPoints: cleanRecord(raw.lastPoints, num),
    seq: seq + RESTORE_SEQ_JUMP,
  };
  const acked = cleanRecord(raw.acked, (v) =>
    Array.isArray(v) ? v.filter((id): id is string => typeof id === 'string' && id.length > 0 && id.length <= 64).slice(-ACK_KEEP) : undefined,
  );
  if (Object.keys(acked).length) state.acked = acked;
  if (isRecord(raw.shared)) state.shared = Object.fromEntries(Object.entries(raw.shared).filter(([k]) => SHARE_KEY.test(k)));
  return state;
}

/** Where a host keeps its room between page loads. `Storage` fits (`localStorage`, `sessionStorage`). */
export interface RoomStorage {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
  removeItem(key: string): void;
}

/**
 * A room kept in `storage` under `key`. Storage that is missing, full or blocked (a private window,
 * a storage-less embed) never throws: `load` finds nothing and `save` does nothing, and the room
 * carries on in memory. Call `save` after every change, `clear` when the game ends.
 */
export function createRoomStore(
  storage: RoomStorage | null | undefined,
  key: string,
  options: { hostId?: string } = {},
): { load(): RoomState | null; save(state: RoomState): void; clear(): void } {
  return {
    load() {
      try {
        return restoreRoom(storage?.getItem(key), options);
      } catch {
        return null;
      }
    },
    save(state) {
      try {
        storage?.setItem(key, serializeRoom(state));
      } catch {
        /* a full or blocked store must not stop the game */
      }
    },
    clear() {
      try {
        storage?.removeItem(key);
      } catch {
        /* nothing to clear */
      }
    },
  };
}

// --- Transport ------------------------------------------------------------------

/** What travels between the host and the players. */
export type RoomMessage =
  /** A player asks the host to apply an event. */
  | { kind: 'intent'; from: string; event: RoomEvent }
  /** The host's room, after every change. */
  | {
      kind: 'state';
      state: RoomState;
      /** The host's clock when it sent this, in ms. Phones use it to read deadlines on the host's time. */
      at?: number;
    }
  /** A client that just arrived asks for the current state. */
  | { kind: 'hello'; from: string }
  /** The host refused a player's intent, and why. */
  | {
      kind: 'rejected';
      to: string;
      event: RoomEvent['type'];
      reason: RoomRejection;
      /** For a refused `submit`: its id, so the player stops sending that move. */
      id?: string;
    };

/**
 * How a room talks. `send` reaches every other client in the room (not the
 * sender); `subscribe` returns an unsubscribe. Wrap any realtime service in
 * these two functions.
 */
export interface RoomTransport<M = RoomMessage> {
  send(message: M): void;
  subscribe(listener: (message: M) => void): () => void;
  /** Optional: release the connection. */
  close?(): void;
}

/**
 * An in-memory room: every `connect()` is a client, and messages arrive on
 * the next microtask, like a network would deliver them. For tests, demos
 * and a host and players on one screen.
 */
export function createMemoryRoomHub<M = RoomMessage>(): { connect(): RoomTransport<M> } {
  const clients = new Set<(message: M) => void>();
  return {
    connect() {
      const own = new Set<(message: M) => void>();
      const deliver = (message: M) => own.forEach((l) => l(message));
      clients.add(deliver);
      return {
        send(message) {
          const copy = JSON.parse(JSON.stringify(message)) as M;
          queueMicrotask(() => clients.forEach((c) => c !== deliver && c(copy)));
        },
        subscribe(listener) {
          own.add(listener);
          return () => own.delete(listener);
        },
        close() {
          clients.delete(deliver);
          own.clear();
        },
      };
    },
  };
}

/**
 * A transport over `BroadcastChannel`: every tab of the same site on this
 * device that opens the same `name` is in the room. Null where the browser
 * has no BroadcastChannel.
 */
export function createBroadcastRoomTransport<M = RoomMessage>(name: string): RoomTransport<M> | null {
  if (typeof BroadcastChannel === 'undefined') return null;
  const channel = new BroadcastChannel(name);
  return {
    send: (message) => channel.postMessage(message),
    subscribe(listener) {
      const handle = (e: MessageEvent<M>) => listener(e.data);
      channel.addEventListener('message', handle);
      return () => channel.removeEventListener('message', handle);
    },
    close: () => channel.close(),
  };
}

import { cleanName, readShared, rejectRoomEvent, type RoomHostEvent, type RoomPlayer, type RoomState } from '@/components/ui/games/room-model';

/**
 * @interlace/ui — games/team-model
 *
 * Teams for a live room: who is on which team, a fair automatic split, a move by hand, and each
 * team's score from the room's own player scores. Pure, so the host and a server run the same
 * rules.
 *
 * The teams live in the room (`RoomState.shared.teams`, written with a `share` event), so a phone
 * that joins late or reconnects gets them with the room state, the newest `seq` wins whatever
 * order messages arrive in, and a host that restores the room restores its teams. Everything
 * read back goes through `readTeams`, which treats the data as untrusted and drops anyone who is
 * no longer in the room.
 *
 * A team's colour is its place in the list: `teamColor(i)` is a `--team-N` token (five of them; a
 * sixth team reuses the first colour), and `teamMark(i)` is the letter that goes with it, so
 * colour is never the only way to tell teams apart.
 */

import { rankEntries } from '@/components/ui/games/leaderboard-model';
import { clampCount, isId, isRecord, shuffled, snakeDeal, smallestIndex, type Random } from '@/components/ui/games/group-model';

/** The key in `RoomState.shared`. */
export const TEAMS_KEY = 'teams';
/** The most teams a room has. */
export const MAX_TEAMS = 12;
/** How many `--team-N` colour tokens there are. */
export const TEAM_COLORS = 5;
const MAX_NAME = 24;

export interface Team {
  /** `t1`, `t2`, … Stable: renaming a team or adding one never changes another's id. */
  id: string;
  name: string;
}

export interface TeamsState {
  /** In order. A team's colour and mark come from its place. */
  teams: Team[];
  /** Team id per player id. A player with no entry is not on a team yet. */
  members: Record<string, string>;
}

/** `count` empty teams (2 to `MAX_TEAMS`), named from `names`, then "Team 3", "Team 4"… */
export function createTeams(count: number, names: readonly string[] = []): TeamsState {
  const n = clampCount(count, 2, MAX_TEAMS);
  return {
    teams: Array.from({ length: n }, (_, i) => ({
      id: `t${i + 1}`,
      name: cleanName(names[i] ?? '', MAX_NAME) || `Team ${i + 1}`,
    })),
    members: {},
  };
}

/** Teams from untrusted data (a `share` value), or null when it is not teams. */
export function decodeTeams(raw: unknown): TeamsState | null {
  if (!isRecord(raw) || !Array.isArray(raw.teams)) return null;
  if (raw.teams.length < 2 || raw.teams.length > MAX_TEAMS) return null;
  const teams: Team[] = [];
  for (const t of raw.teams) {
    if (!isRecord(t) || !isId(t.id) || typeof t.name !== 'string') return null;
    if (teams.some((x) => x.id === t.id)) return null;
    teams.push({ id: t.id, name: cleanName(t.name, MAX_NAME) || `Team ${teams.length + 1}` });
  }
  const members = Object.entries(isRecord(raw.members) ? raw.members : {}).filter(
    ([id, team]) => id !== '__proto__' && typeof team === 'string' && teams.some((t) => t.id === team),
  ) as [string, string][];
  return { teams, members: Object.fromEntries(members) };
}

/** The room's teams, with anyone no longer in the room dropped; null when none are set. */
export function readTeams(room: Pick<RoomState, 'shared' | 'players'> | null | undefined): TeamsState | null {
  const teams = readShared(room, TEAMS_KEY, decodeTeams);
  if (!teams || !room) return teams;
  const here = new Set(room.players.map((p) => p.id));
  return { ...teams, members: Object.fromEntries(Object.entries(teams.members).filter(([id]) => here.has(id))) };
}

/** The host event that sets the teams for every screen, or clears them with null. */
export function teamsEvent(teams: TeamsState | null): RoomHostEvent {
  return { type: 'share', key: TEAMS_KEY, value: teams };
}

/** Whether the room would take these teams (the size limit on `shared` is the only way not). */
export function teamsFit(room: RoomState, teams: TeamsState): boolean {
  return rejectRoomEvent(room, teamsEvent(teams), room.hostId) === null;
}

/** The index of a team in the list, or -1. Its colour and mark come from it. */
export function teamIndex(teams: TeamsState, teamId: string): number {
  return teams.teams.findIndex((t) => t.id === teamId);
}

/** The team a player is on, or null. */
export function teamOf(teams: TeamsState, playerId: string): Team | null {
  const id = Object.hasOwn(teams.members, playerId) ? teams.members[playerId] : undefined;
  return teams.teams.find((t) => t.id === id) ?? null;
}

/** A team's players, in the order they joined the room. */
export function membersOf(teams: TeamsState, teamId: string, players: readonly RoomPlayer[]): RoomPlayer[] {
  return players.filter((p) => Object.hasOwn(teams.members, p.id) && teams.members[p.id] === teamId);
}

/** Players on no team yet, in the order they joined. */
export function unassigned(teams: TeamsState, players: readonly RoomPlayer[]): RoomPlayer[] {
  return players.filter((p) => !teamOf(teams, p.id));
}

/** The `var()` of a team's colour token: `var(--team-1)` … `var(--team-5)`, then round again. */
export function teamColor(index: number): string {
  return `var(--team-${(Math.max(0, index) % TEAM_COLORS) + 1})`;
}

/** The letter that goes with a team's colour: A, B, C … (it repeats after Z, which no room reaches). */
export function teamMark(index: number): string {
  return String.fromCharCode(65 + (Math.max(0, index) % 26));
}

/** Moves a player to a team, or off every team with null. The same object when nothing changes. */
export function moveToTeam(teams: TeamsState, playerId: string, teamId: string | null): TeamsState {
  const now = teamOf(teams, playerId)?.id ?? null;
  if (teamId === now) return teams;
  if (teamId === null) {
    const { [playerId]: _gone, ...members } = teams.members;
    return { ...teams, members };
  }
  if (!teams.teams.some((t) => t.id === teamId)) return teams;
  return { ...teams, members: { ...teams.members, [playerId]: teamId } };
}

/** Renames a team. The same object when the name is empty, unknown or unchanged. */
export function renameTeam(teams: TeamsState, teamId: string, name: string): TeamsState {
  const clean = cleanName(name, MAX_NAME);
  const team = teams.teams.find((t) => t.id === teamId);
  if (!team || !clean || team.name === clean) return teams;
  return { ...teams, teams: teams.teams.map((t) => (t === team ? { ...t, name: clean } : t)) };
}

/**
 * Changes the number of teams (2 to `MAX_TEAMS`). New teams are empty; the players of a team that
 * goes become unassigned (`placeNewcomers` or `autoBalance` then places them).
 */
export function resizeTeams(teams: TeamsState, count: number): TeamsState {
  const n = clampCount(count, 2, MAX_TEAMS);
  if (n === teams.teams.length) return teams;
  const kept = teams.teams.slice(0, n);
  const added = Array.from({ length: Math.max(0, n - kept.length) }, (_, i) => {
    const place = kept.length + i + 1;
    return { id: `t${nextNumber(teams.teams, place)}`, name: `Team ${place}` };
  });
  const all = [...kept, ...added];
  return {
    teams: all,
    members: Object.fromEntries(Object.entries(teams.members).filter(([, id]) => all.some((t) => t.id === id))),
  };
}

/** The lowest `tN` number at or above `from` that no team uses (a removed team's number is free again). */
function nextNumber(teams: readonly Team[], from: number): number {
  let n = from;
  while (teams.some((t) => t.id === `t${n}`)) n++;
  return n;
}

/** How many of `players` are on each team, in team order. */
function sizes(teams: TeamsState, players: readonly RoomPlayer[]): number[] {
  return teams.teams.map((t) => membersOf(teams, t.id, players).length);
}

/**
 * Puts every player with no team on the smallest one (the first on a tie), one by one. Call it
 * when someone joins late. The same object when everyone already has a team.
 */
export function placeNewcomers(teams: TeamsState, players: readonly RoomPlayer[]): TeamsState {
  const loose = unassigned(teams, players);
  if (!loose.length) return teams;
  const count = sizes(teams, players);
  const members = { ...teams.members };
  for (const p of loose) {
    const at = smallestIndex(count);
    members[p.id] = (teams.teams[at] as Team).id;
    count[at] = (count[at] as number) + 1;
  }
  return { ...teams, members };
}

export interface BalanceOptions {
  /** Points so far per player id. Strong players are spread across teams instead of piling onto one. */
  scores?: Record<string, number>;
  /** @default Math.random. Pass `seededRandom(n)` for a split you can repeat. */
  random?: Random;
}

/**
 * Splits every player across the teams so sizes differ by at most one. Players are shuffled, then
 * ordered by score (best first) and dealt 1 2 3 3 2 1 …, so with scores the teams start level and
 * without them it is a fair random split. Everyone is placed again, whoever was where.
 */
export function autoBalance(teams: TeamsState, players: readonly RoomPlayer[], options: BalanceOptions = {}): TeamsState {
  const { scores = {}, random } = options;
  const score = (id: string) => (Object.hasOwn(scores, id) && Number.isFinite(scores[id]) ? (scores[id] as number) : 0);
  const order = shuffled(players, random)
    .sort((a, b) => score(b.id) - score(a.id))
    .map((p) => p.id);
  const piles = snakeDeal(order, teams.teams.length);
  const members: Record<string, string> = {};
  piles.forEach((ids, i) => ids.forEach((id) => (members[id] = (teams.teams[i] as Team).id)));
  return { ...teams, members };
}

export interface TeamStanding {
  id: string;
  name: string;
  /** The team's place in the list: its colour and mark. */
  index: number;
  /** 1-based; ties share a rank. */
  rank: number;
  tied: boolean;
  /** Players on the team. */
  size: number;
  /** The players' points added up. */
  total: number;
  /** `total` per player, to one decimal; 0 for an empty team. */
  average: number;
  /** Points the team's players won in the last revealed round. */
  gained: number;
}

/**
 * Each team's score from the room's player scores, best first. `by` decides what ranks:
 * `average` (default) is fair when teams differ in size by one; `total` rewards a bigger team.
 */
export function teamStandings(
  teams: TeamsState,
  room: Pick<RoomState, 'players' | 'scores' | 'lastPoints'>,
  by: 'average' | 'total' = 'average',
): TeamStanding[] {
  const sum = (ids: RoomPlayer[], from: Record<string, number>) =>
    ids.reduce((acc, p) => acc + (Object.hasOwn(from, p.id) ? (from[p.id] as number) : 0), 0);
  const rows = teams.teams.map((t, index) => {
    const people = membersOf(teams, t.id, room.players);
    const total = sum(people, room.scores);
    const average = people.length ? Math.round((total / people.length) * 10) / 10 : 0;
    return { id: t.id, name: t.name, index, size: people.length, total, average, gained: sum(people, room.lastPoints) };
  });
  const ranked = rankEntries(rows.map((r) => ({ id: r.id, name: r.name, score: by === 'total' ? r.total : r.average })));
  return ranked.map((r) => ({
    ...(rows.find((x) => x.id === r.id) as (typeof rows)[number]),
    rank: r.rank,
    tied: r.tied,
  }));
}
